Save this as `index.html` and open it in a browser. It uses only the Three.js core ES module from cdnjs and includes direct mouse/touch camera controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Buoy Tender — Working Deck</title>

  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #0b2635;
    }

    #viewport {
      position: fixed;
      inset: 0;
    }

    #viewport canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    #viewport canvas:active {
      cursor: grabbing;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at 50% 45%, transparent 45%, rgba(2, 18, 27, 0.34) 100%),
        linear-gradient(180deg, rgba(4, 25, 37, 0.18), transparent 25%);
    }

    .header {
      position: fixed;
      top: 24px;
      left: 26px;
      z-index: 5;
      pointer-events: none;
      color: #eefaff;
      text-shadow: 0 2px 18px rgba(0, 20, 30, 0.5);
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 9px;
      margin-bottom: 7px;
      color: #8de1e8;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.2em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      width: 24px;
      height: 2px;
      content: "";
      background: #75e2e8;
      box-shadow: 0 0 12px rgba(117, 226, 232, 0.6);
    }

    h1 {
      margin: 0;
      font-size: clamp(25px, 4vw, 42px);
      font-weight: 760;
      letter-spacing: -0.045em;
      line-height: 1;
    }

    .subtitle {
      margin-top: 8px;
      color: rgba(231, 247, 252, 0.72);
      font-size: 13px;
      letter-spacing: 0.02em;
    }

    .status-panel {
      position: fixed;
      top: 24px;
      right: 24px;
      z-index: 5;
      width: 220px;
      padding: 16px 17px;
      border: 1px solid rgba(166, 232, 239, 0.18);
      border-radius: 14px;
      background: rgba(7, 31, 43, 0.68);
      box-shadow: 0 14px 40px rgba(0, 20, 30, 0.2);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
    }

    .status-title {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 12px;
      color: #dffaff;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .live-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #66f0b0;
      box-shadow: 0 0 10px #66f0b0;
    }

    .status-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 7px 0;
      border-top: 1px solid rgba(180, 232, 239, 0.1);
      color: rgba(225, 244, 249, 0.68);
      font-size: 11px;
    }

    .status-row strong {
      color: #8de1e8;
      font-size: 10px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .controls {
      position: fixed;
      left: 50%;
      bottom: 22px;
      z-index: 5;
      transform: translateX(-50%);
      display: flex;
      align-items: center;
      gap: 15px;
      padding: 10px 14px;
      border: 1px solid rgba(166, 232, 239, 0.16);
      border-radius: 999px;
      background: rgba(7, 31, 43, 0.65);
      color: rgba(231, 247, 252, 0.72);
      font-size: 11px;
      white-space: nowrap;
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
    }

    .controls span {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .key {
      min-width: 22px;
      padding: 4px 6px;
      border: 1px solid rgba(190, 235, 241, 0.22);
      border-radius: 5px;
      color: #d9f4f7;
      background: rgba(255, 255, 255, 0.05);
      font-size: 9px;
      text-align: center;
    }

    button {
      padding: 8px 12px;
      border: 1px solid rgba(132, 226, 235, 0.25);
      border-radius: 999px;
      color: #e8fbff;
      background: rgba(63, 173, 187, 0.2);
      font: inherit;
      font-size: 10px;
      font-weight: 750;
      cursor: pointer;
      transition: background 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: rgba(84, 199, 211, 0.34);
      transform: translateY(-1px);
    }

    @media (max-width: 700px) {
      .header {
        top: 17px;
        left: 17px;
      }

      .status-panel {
        top: auto;
        right: 14px;
        bottom: 68px;
        width: 190px;
        padding: 12px 14px;
      }

      .status-row {
        padding: 5px 0;
      }

      .controls {
        bottom: 14px;
        width: calc(100% - 28px);
        justify-content: center;
        gap: 9px;
        padding: 9px 11px;
      }

      .controls .desktop-hint {
        display: none;
      }
    }
  </style>
</head>

<body>
  <div id="viewport" aria-label="Interactive 3D buoy tender scene"></div>
  <div class="vignette"></div>

  <header class="header">
    <div class="eyebrow">Marine Operations</div>
    <h1>Buoy Tender T-07</h1>
    <div class="subtitle">Stern crane station · active buoy recovery</div>
  </header>

  <aside class="status-panel">
    <div class="status-title">
      <span>Operation status</span>
      <span class="live-dot"></span>
    </div>
    <div class="status-row">
      <span>Crane</span>
      <strong>Online</strong>
    </div>
    <div class="status-row">
      <span>Target buoy</span>
      <strong>B-14</strong>
    </div>
    <div class="status-row">
      <span>Sea state</span>
      <strong>0.4 m</strong>
    </div>
    <div class="status-row">
      <span>Wind</span>
      <strong>12 kn</strong>
    </div>
  </aside>

  <div class="controls">
    <span><b class="key">DRAG</b> Orbit</span>
    <span><b class="key">WHEEL</b> Zoom</span>
    <span class="desktop-hint"><b class="key">RIGHT</b> Pan</span>
    <button id="reset-view" type="button">Reset view</button>
  </div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer, scene, camera
    // -------------------------------------------------------------------------

    const viewport = document.getElementById("viewport");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.setAttribute("aria-label", "Three.js buoy tender scene");
    viewport.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x8dc8d9);
    scene.fog = new THREE.FogExp2(0x8dc8d9, 0.017);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      180
    );

    const cameraTarget = new THREE.Vector3(0, 1.65, -0.7);
    const spherical = new THREE.Spherical(15.5, 1.14, 0.72);

    function updateCamera() {
      camera.position.setFromSpherical(spherical).add(cameraTarget);
      camera.lookAt(cameraTarget);
    }

    updateCamera();

    // -------------------------------------------------------------------------
    // Lighting
    // -------------------------------------------------------------------------

    const hemisphere = new THREE.HemisphereLight(0xd9f4ff, 0x24464d, 2.1);
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xfff1d3, 3.2);
    sun.position.set(-9, 15, 10);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -18;
    sun.shadow.camera.right = 18;
    sun.shadow.camera.top = 18;
    sun.shadow.camera.bottom = -18;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 50;
    sun.shadow.bias = -0.0003;
    sun.shadow.normalBias = 0.025;
    scene.add(sun);

    const fill = new THREE.DirectionalLight(0x8bd9eb, 0.8);
    fill.position.set(10, 7, -12);
    scene.add(fill);

    // -------------------------------------------------------------------------
    // Materials and geometry helpers
    // -------------------------------------------------------------------------

    const material = (color, roughness = 0.6, metalness = 0.05) =>
      new THREE.MeshStandardMaterial({ color, roughness, metalness });

    const M = {
      hull: new THREE.MeshStandardMaterial({
        vertexColors: true,
        roughness: 0.43,
        metalness: 0.18,
        flatShading: true
      }),
      deckTop: new THREE.MeshStandardMaterial({
        color: 0xffffff,
        roughness: 0.9,
        metalness: 0.02
      }),
      deckEdge: material(0x82785f, 0.88),
      orange: material(0xf28a2b, 0.48, 0.22),
      orangeDark: material(0xb95718, 0.55, 0.2),
      darkMetal: material(0x263840, 0.42, 0.68),
      steel: material(0x9ba9ad, 0.3, 0.8),
      black: material(0x10191d, 0.68, 0.25),
      rubber: material(0x172126, 0.95),
      white: material(0xe8eef0, 0.55, 0.08),
      yellow: material(0xf5c82e, 0.46, 0.12),
      red: material(0xb93530, 0.5, 0.12),
      green: material(0x36b978, 0.45, 0.1),
      blue: material(0x176787, 0.55, 0.25),
      wood: material(0x806044, 0.9),
      screen: new THREE.MeshStandardMaterial({
        color: 0x0b3440,
        emissive: 0x0b7890,
        emissiveIntensity: 0.65,
        roughness: 0.25
      }),
      lampWhite: new THREE.MeshStandardMaterial({
        color: 0xfff4c2,
        emissive: 0xffe58a,
        emissiveIntensity: 2.2
      }),
      lampRed: new THREE.MeshStandardMaterial({
        color: 0xff3535,
        emissive: 0xff1616,
        emissiveIntensity: 2.4
      }),
      lampGreen: new THREE.MeshStandardMaterial({
        color: 0x43ff9a,
        emissive: 0x16d965,
        emissiveIntensity: 2.4
      })
    };

    const boat = new THREE.Group();
    boat.position.y = 0.12;
    scene.add(boat);

    function addBox(parent, size, position, mat, castShadow = true) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(size[0], size[1], size[2]),
        mat
      );
      mesh.position.set(...position);
      mesh.castShadow = castShadow;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addCylinder(
      parent,
      topRadius,
      bottomRadius,
      height,
      position,
      mat,
      radialSegments = 16
    ) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(
          topRadius,
          bottomRadius,
          height,
          radialSegments
        ),
        mat
      );
      mesh.position.set(...position);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addSphere(parent, radius, position, mat, widthSegments = 20) {
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(radius, widthSegments, 14),
        mat
      );
      mesh.position.set(...position);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    const Y_AXIS = new THREE.Vector3(0, 1, 0);

    function setBeam(mesh, a, b) {
      const start = a.isVector3 ? a : new THREE.Vector3(...a);
      const end = b.isVector3 ? b : new THREE.Vector3(...b);
      const direction = new THREE.Vector3().subVectors(end, start);
      const length = direction.length();

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.scale.set(1, length, 1);
      mesh.quaternion.setFromUnitVectors(Y_AXIS, direction.normalize());
    }

    function makeBeam(parent, a, b, radius, mat) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radius, radius, 1, 10),
        mat
      );
      setBeam(mesh, a, b);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function makeTorus(
      parent,
      radius,
      tube,
      position,
      mat,
      rotation = [0, 0, 0],
      segments = 32
    ) {
      const mesh = new THREE.Mesh(
        new THREE.TorusGeometry(radius, tube, 8, segments),
        mat
      );
      mesh.position.set(...position);
      mesh.rotation.set(...rotation);
      mesh.castShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // -------------------------------------------------------------------------
    // Procedural non-slip deck texture
    // -------------------------------------------------------------------------

    function createDeckTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 512;
      canvas.height = 512;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#b4aa8e";
      ctx.fillRect(0, 0, 512, 512);

      let seed = 731;
      const random = () => {
        seed = (seed * 16807) % 2147483647;
        return (seed - 1) / 2147483646;
      };

      for (let x = 0; x < 512; x += 64) {
        ctx.fillStyle = `rgba(73, 66, 51, ${0.08 + random() * 0.12})`;
        ctx.fillRect(x, 0, 3, 512);
        ctx.fillStyle = "rgba(255,255,255,0.12)";
        ctx.fillRect(x + 4, 0, 2, 512);
      }

      for (let i = 0; i < 900; i++) {
        const x = random() * 512;
        const y = random() * 512;
        const alpha = 0.025 + random() * 0.05;
        ctx.fillStyle = `rgba(25,35,35,${alpha})`;
        ctx.fillRect(x, y, 1 + random() * 2, 1);
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
      return texture;
    }

    M.deckTop.map = createDeckTexture();
    M.deckTop.map.repeat.set(2.2, 1.5);

    // -------------------------------------------------------------------------
    // Hull
    // -------------------------------------------------------------------------

    const sections = [
      { z: -5.20, width: 0.18, top: 0.36, bottom: -1.05 },
      { z: -4.85, width: 1.18, top: 0.52, bottom: -0.98 },
      { z: -3.55, width: 2.15, top: 0.61, bottom: -0.82 },
      { z: -1.15, width: 2.55, top: 0.64, bottom: -0.66 },
      { z: 1.35, width: 2.62, top: 0.62, bottom: -0.56 },
      { z: 3.35, width: 2.22, top: 0.51, bottom: -0.38 },
      { z: 4.85, width: 1.35, top: 0.31, bottom: -0.12 },
      { z: 6.05, width: 0.42, top: 0.16, bottom: 0.00 },
      { z: 6.90, width: 0.04, top: 0.10, bottom: 0.00 }
    ];

    const hullPositions = [];
    const hullColors = [];
    const hullIndices = [];

    const navy = new THREE.Color(0x183d50);
    const darkRed = new THREE.Color(0x672625);
    const red = new THREE.Color(0x9e342a);

    for (const section of sections) {
      hullPositions.push(
        0, section.bottom, section.z,
        -section.width, section.top, section.z,
        section.width, section.top, section.z
      );
    }

    const color = new THREE.Color();

    for (const section of sections) {
      if (section.bottom < -0.35) {
        color.copy(red);
      } else if (section.bottom < 0.15) {
        color.copy(darkRed).lerp(red, 0.5);
      } else {
        color.copy(navy);
      }

      hullColors.push(
        color.r, color.g, color.b,
        color.r, color.g, color.b,
        color.r, color.g, color.b
      );
    }

    for (let i = 0; i < sections.length - 1; i++) {
      const a = i * 3;
      const b = (i + 1) * 3;

      const portBottom = a;
      const portTop = a + 1;
      const starboardTop = a + 2;
      const nextPortBottom = b;
      const nextPortTop = b + 1;
      const nextStarboardTop = b + 2;

      hullIndices.push(
        portBottom, nextPortBottom, portTop,
        portTop, nextPortBottom, nextPortTop,

        starboardTop, portTop, nextStarboardTop,
        portTop, nextStarboardTop, nextPortTop
      );
    }

    const hullGeometry = new THREE.BufferGeometry();
    hullGeometry.setAttribute(
      "position",
      new THREE.Float32BufferAttribute(hullPositions, 3)
    );
    hullGeometry.setAttribute(
      "color",
      new THREE.Float32BufferAttribute(hullColors, 3)
    );
    hullGeometry.setIndex(hullIndices);
    hullGeometry.computeVertexNormals();

    const hull = new THREE.Mesh(hullGeometry, M.hull);
    hull.castShadow = true;
    hull.receiveShadow = true;
    boat.add(hull);

    // White rubbing strakes along both sides.
    for (const side of [-1, 1]) {
      const points = sections.map((section) => {
        const width = section.width - 0.035;
        return new THREE.Vector3(
          side * width,
          0.24,
          section.z
        );
      });

      const curve = new THREE.CatmullRomCurve3(points);
      const rail = new THREE.Mesh(
        new THREE.TubeGeometry(curve, 70, 0.055, 7, false),
        M.white
      );
      rail.castShadow = true;
      boat.add(rail);
    }

    // Main working deck.
    const deckShape = new THREE.Shape();
    deckShape.moveTo(-0.18, -5.20);
    deckShape.lineTo(-1.10, -4.95);
    deckShape.lineTo(-2.05, -3.70);
    deckShape.lineTo(-2.45, -1.20);
    deckShape.lineTo(-2.55, 1.20);
    deckShape.lineTo(-2.40, 3.20);
    deckShape.lineTo(-1.75, 4.80);
    deckShape.lineTo(-0.65, 5.85);
    deckShape.lineTo(0.65, 5.85);
    deckShape.lineTo(1.75, 4.80);
    deckShape.lineTo(2.40, 3.20);
    deckShape.lineTo(2.55, 1.20);
    deckShape.lineTo(2.45, -1.20);
    deckShape.lineTo(2.05, -3.70);
    deckShape.lineTo(1.10, -4.95);
    deckShape.closePath();

    const deckGeometry = new THREE.ExtrudeGeometry(deckShape, {
      depth: 0.14,
      bevelEnabled: true,
      bevelSize: 0.035,
      bevelThickness: 0.035,
      bevelSegments: 2,
      steps: 1
    });

    deckGeometry.rotateX(Math.PI / 2);

    const deck = new THREE.Mesh(deckGeometry, [M.deckTop, M.deckEdge]);
    deck.position.y = 0.72;
    deck.castShadow = true;
    deck.receiveShadow = true;
    boat.add(deck);

    // Raised stern work platform.
    addBox(boat, [4.25, 0.12, 2.25], [0, 0.78, -3.85], M.darkMetal);
    addBox(boat, [4.35, 0.08, 0.10], [0, 0.86, -4.98], M.orangeDark);

    // -------------------------------------------------------------------------
    // Railings
    // -------------------------------------------------------------------------

    function addRail(a, b, baseY = 0.84) {
      const topY = baseY + 0.62;
      const midY = baseY + 0.31;

      makeBeam(boat, [a[0], topY, a[2]], [b[0], topY, b[2]], 0.035, M.steel);
      makeBeam(boat, [a[0], midY, a[2]], [b[0], midY, b[2]], 0.025, M.steel);

      const length = Math.hypot(b[0] - a[0], b[2] - a[2]);
      const postCount = Math.max(1, Math.ceil(length / 1.15));

      for (let i = 0; i <= postCount; i++) {
        const t = i / postCount;
        const x = THREE.MathUtils.lerp(a[0], b[0], t);
        const z = THREE.MathUtils.lerp(a[2], b[2], t);
        makeBeam(boat, [x, baseY, z], [x, topY, z], 0.032, M.steel);
      }
    }

    const railPoints = [
      [-2.43, -4.65],
      [-2.43, -2.80],
      [-2.43, 0.00],
      [-2.35, 2.35],
      [-1.75, 4.65]
    ];

    const starboardPoints = railPoints.map((p) => [p[1], p[0]]);

    for (const points of [railPoints, starboardPoints]) {
      for (let i = 0; i < points.length - 1; i++) {
        addRail(points[i], points[i + 1]);
      }
    }

    addRail([-1.95, -4.72], [1.95, -4.72]);
    addRail([-2.43, -4.65], [-1.95, -4.72]);
    addRail([2.43, -4.65], [1.95, -4.72]);

    // -------------------------------------------------------------------------
    // Hull lettering
    // -------------------------------------------------------------------------

    function createHullSign() {
      const canvas = document.createElement("canvas");
      canvas.width = 1024;
      canvas.height = 256;
      const ctx = canvas.getContext("2d");

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "#e5eef0";
      ctx.font = "800 92px Arial, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("BOUY TENDER", 512, 112);
      ctx.fillStyle = "#8de1e8";
      ctx.font = "700 35px Arial, sans-serif";
      ctx.fillText("T-07  •  CREW 04", 512, 177);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;

      const sign = new THREE.Mesh(
        new THREE.PlaneGeometry(2.45, 0.61),
        new THREE.MeshBasicMaterial({
          map: texture,
          transparent: true,
          depthWrite: false,
          side: THREE.DoubleSide
        })
      );

      sign.position.set(-2.558, 0.16, -0.35);
      sign.rotation.y = -Math.PI / 2;
      boat.add(sign);
    }

    createHullSign();

    // -------------------------------------------------------------------------
    // Stern crane
    // -------------------------------------------------------------------------

    const crane = new THREE.Group();
    boat.add(crane);

    addCylinder(crane, 0.62, 0.72, 0.72, [0, 1.05, -3.55], M.darkMetal);
    addCylinder(crane, 0.68, 0.68, 0.13, [0, 1.48, -3.55], M.orange);

    makeBeam(crane, [-1.15, 1.38, -3.55], [0, 3.20, -3.55], 0.105, M.orange);
    makeBeam(crane, [1.15, 1.38, -3.55], [0, 3.20, -3.55], 0.105, M.orange);
    makeBeam(crane, [-0.78, 2.10, -3.55], [0.78, 2.10, -3.55], 0.075, M.orangeDark);

    const boomPivot = new THREE.Vector3(0, 3.20, -3.55);
    const boomTip = new THREE.Vector3(0, 5.85, -6.15);

